from itertools import combinations
from typing import FrozenSet, Hashable, Sequence, TypeVar
V = TypeVar("V", bound=Hashable)
def missing_common_witness(vertices: Sequence[V], records: Sequence[FrozenSet[V]]) -> list[FrozenSet[V]]:
    edges = {frozenset(p) for record in records for p in combinations(record, 2)}
    failures: list[FrozenSet[V]] = []
    for triple_tuple in combinations(vertices, 3):
        triple = frozenset(triple_tuple)
        if all(frozenset(p) in edges for p in combinations(triple, 2)) and not any(triple <= r for r in records):
            failures.append(triple)
    return failures

